package pty

import (
	"nestedterm/internal/terminal"
)

// RunSessionIO pumps output from the PTY session into the terminal emulator,
// drains any query responses back to the PTY, and notifies on redraws and process exits.
func RunSessionIO(
	sess *PTYSession,
	emu terminal.TerminalEmulator,
	onRedraw func(),
	onExit func(code int),
) {
	buf := make([]byte, 8192)

	for {
		n, err := sess.PTY.Read(buf)
		if n > 0 {
			_, _ = emu.Write(buf[:n])

			// Drain query replies generated by the emulator and return them to the PTY
			responses := emu.TakeResponses()
			if len(responses) > 0 {
				_, _ = sess.Write(responses)
			}

			if onRedraw != nil {
				onRedraw()
			}
		}

		if err != nil {
			break
		}
	}

	// Session read ended (PTY closed or process exited)
	exitCode, _ := sess.Wait()
	code := 0
	if exitCode != nil {
		code = *exitCode
	}

	if onExit != nil {
		onExit(code)
	}
	if onRedraw != nil {
		onRedraw()
	}
}
